        if (
            s1.get("direction") in ("increasing", "decreasing")
            and s2.get("direction") in ("increasing", "decreasing")
            and s1.get("direction") != s2.get("direction")
        ):
            log("NOTE", "CROSS", "directions_differ", f"S1={s1.get('direction')} S2={s2.get('direction')}")


if __name__ == "__main__":
